struct Matrix {
    private final class Storage {
        var values: [Double]
        init(_ v: [Double]) { values = v }
    }
    private var storage: Storage

    init(count: Int) { storage = Storage(Array(repeating: 0, count: count)) }

    subscript(i: Int) -> Double {
        get { storage.values[i] }
        set {
            if !isKnownUniquelyReferenced(&storage) {   // shared? copy first
                storage = Storage(storage.values)
            }
            storage.values[i] = newValue
        }
    }
}
